<script setup lang="ts">
import { nextTick, onMounted, onUnmounted, watch } from 'vue'
import { useRoute } from 'vue-router'
import LanguageToggle from './components/LanguageToggle.vue'
import TeacherAttendanceSidebar from './components/TeacherAttendanceSidebar.vue'
import { useLocaleStore } from './stores/locale'

const locale = useLocaleStore(); const route = useRoute(); let observer: MutationObserver | null = null; let enhancing = false
const originalText = new WeakMap<Text, string>(); const originalAttrs = new WeakMap<HTMLElement, Record<string, string>>(); const enhanced = new WeakMap<HTMLSelectElement, { button: HTMLButtonElement; menu: HTMLDivElement }>()
function renderSelect(select: HTMLSelectElement, ui: { button: HTMLButtonElement; menu: HTMLDivElement }) { ui.button.querySelector('span')!.textContent = select.selectedOptions[0]?.textContent?.trim() || ''; ui.menu.replaceChildren(); Array.from(select.options).forEach((option, index) => { const item = document.createElement('button'); item.type = 'button'; item.className = 'modern-option'; item.disabled = option.disabled; item.setAttribute('role', 'option'); item.setAttribute('aria-selected', String(option.selected)); item.innerHTML = `<span>${option.textContent || ''}</span>${option.selected ? '<b>✓</b>' : ''}`; item.addEventListener('click', () => { if (option.disabled) return; select.selectedIndex = index; select.dispatchEvent(new Event('change', { bubbles: true })); ui.menu.classList.remove('visible'); ui.button.setAttribute('aria-expanded', 'false') }); ui.menu.append(item) }) }
function enhanceSelects() { if (enhancing) return; enhancing = true; document.querySelectorAll<HTMLSelectElement>('select:not([data-modern-select])').forEach((select) => { const shell = document.createElement('div'); shell.className = 'modern-select-shell'; select.parentNode?.insertBefore(shell, select); shell.append(select); select.dataset.modernSelect = 'true'; select.classList.add('modern-select-native'); const button = document.createElement('button'); button.type = 'button'; button.className = 'modern-select-button'; button.setAttribute('aria-haspopup', 'listbox'); button.setAttribute('aria-expanded', 'false'); button.innerHTML = '<span></span><i></i>'; const menu = document.createElement('div'); menu.className = 'modern-select-options'; menu.setAttribute('role', 'listbox'); shell.append(button, menu); const ui = { button, menu }; enhanced.set(select, ui); renderSelect(select, ui); button.addEventListener('click', () => { document.querySelectorAll('.modern-select-options.visible').forEach((open) => open.classList.remove('visible')); menu.classList.toggle('visible'); button.setAttribute('aria-expanded', String(menu.classList.contains('visible'))); renderSelect(select, ui) }); button.addEventListener('keydown', (event) => { if (event.key === 'Escape' || event.key === 'Tab') menu.classList.remove('visible'); if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); button.click() } }); select.addEventListener('change', () => renderSelect(select, ui)) }); enhancing = false }
function refreshEnhancedSelects() { document.querySelectorAll<HTMLSelectElement>('select[data-modern-select]').forEach((select) => { const ui = enhanced.get(select); if (ui) renderSelect(select, ui) }) }
function translateDom() { const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); let node: Node | null; while ((node = walker.nextNode())) { const text = node as Text; if (!originalText.has(text)) originalText.set(text, text.nodeValue || ''); const source = originalText.get(text) || ''; const trimmed = source.trim(); if (!trimmed) continue; const translated = locale.translateText(trimmed); text.nodeValue = locale.locale === 'ar' ? source.replace(trimmed, translated) : source } document.querySelectorAll<HTMLElement>('[placeholder],[title],[aria-label]').forEach((element) => { const attrs = originalAttrs.get(element) || {}; for (const key of ['placeholder', 'title', 'aria-label']) { const value = element.getAttribute(key); if (value && !attrs[key]) attrs[key] = value; const source = attrs[key]; if (source) element.setAttribute(key, locale.locale === 'ar' ? locale.translateText(source) : source) } originalAttrs.set(element, attrs) }); enhanceSelects() }
function closeDropdowns(event: MouseEvent) { if ((event.target as HTMLElement).closest('.modern-select-shell')) return; document.querySelectorAll('.modern-select-options.visible').forEach((menu) => menu.classList.remove('visible')) }
onMounted(() => { locale.apply(); translateDom(); document.addEventListener('click', closeDropdowns); observer = new MutationObserver(() => translateDom()); observer.observe(document.body, { childList: true, subtree: true }) })
watch(() => locale.locale, async () => { locale.apply(); await nextTick(); translateDom(); refreshEnhancedSelects() })
onUnmounted(() => { observer?.disconnect(); document.removeEventListener('click', closeDropdowns) })
</script>
<template><TeacherAttendanceSidebar v-if="route.path === '/teacher/attendance'"/><RouterView/><LanguageToggle/></template>
